import{_ as a}from"./chunks/d0012_front_1920x800.Dwvn5mWx.js";import{_ as r}from"./chunks/dexi_5.Dd2VtMp7.js";import{_ as o}from"./chunks/kit_no_props.CEjWpPFC.js";import{_ as t,o as i,c as l,al as n}from"./chunks/framework.7vp1BMOE.js";const k=JSON.parse('{"title":"PX4 Developer Kits","description":"","frontmatter":{},"headers":[],"relativePath":"en/dev_kits/index.md","filePath":"en/dev_kits/index.md"}'),s={name:"en/dev_kits/index.md"};function d(p,e,c,h,m,u){return i(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="px4-developer-kits" tabindex="-1">PX4 Developer Kits <a class="header-anchor" href="#px4-developer-kits" aria-label="Permalink to &quot;PX4 Developer Kits&quot;">​</a></h1><p>Official PX4 Developer Kits are the recommended way to get flying hardware for PX4 application development.</p><p>Kits that carry the <em>Official PX4 Developer Kit</em> designation are certified by the PX4 maintainer team to meet the requirements of the <a href="./../hardware/dev_kit_program">Developer Kit Program</a>:</p><ul><li>A flight controller that meets the latest Pixhawk standard, or matches its capabilities</li><li>The latest stable PX4 release, pre-installed</li><li>Pre-assembled, or assembly that requires no technical skill (no soldering)</li><li>A guide, a focused tutorial, and a printed reference sheet included in the box</li><li>Third-party build quality verification</li></ul><p>This means you can take any of the kits below out of the box and be developing against a current, supported PX4 stack in hours, not weeks.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Manufacturers who want their kit certified should read the <a href="./../hardware/dev_kit_program">Developer Kit Program</a> documentation.</p></div><h2 id="modalai-starling-2-max" tabindex="-1">ModalAI Starling 2 Max <a class="header-anchor" href="#modalai-starling-2-max" aria-label="Permalink to &quot;ModalAI Starling 2 Max&quot;">​</a></h2><p><img src="'+a+'" alt="Front view of the ModalAI Starling 2 Max"></p><p>The <a href="https://www.modalai.com/products/starling-2-max" target="_blank" rel="noreferrer">Starling 2 Max</a> is an NDAA-compliant, ready-to-fly development drone built around the <a href="./../flight_controller/modalai_voxl_2">VOXL 2</a>, which combines the flight controller and a powerful companion computer in a single package.</p><p>It is designed for computer-vision development (SLAM, GPS-denied navigation, long-range dead reckoning), carries a 500 g payload, and flies for up to 55 minutes. The open source <a href="https://gitlab.com/voxl-public/voxl-sdk" target="_blank" rel="noreferrer">VOXL SDK</a> ships with pre-configured autonomy models, and the platform supports ROS 2 and MAVSDK workflows on the onboard computer.</p><ul><li><a href="./../complete_vehicles_mc/modalai_starling">PX4 documentation</a></li><li><a href="https://docs.modalai.com/starling-2-max/" target="_blank" rel="noreferrer">Manufacturer documentation</a></li></ul><h2 id="droneblocks-dexi-5" tabindex="-1">DroneBlocks DEXI 5 <a class="header-anchor" href="#droneblocks-dexi-5" aria-label="Permalink to &quot;DroneBlocks DEXI 5&quot;">​</a></h2><p><img src="'+r+'" alt="DroneBlocks DEXI 5 in flight"></p><p>The <a href="https://droneblocks.io/program/dexi-5-px4-stem-drone-kit/" target="_blank" rel="noreferrer">DEXI 5</a> is an NDAA-compliant STEM and development drone kit built around an all-in-one PX4 flight controller with integrated optical flow (for GPS-denied indoor flight) and a Raspberry Pi companion computer with camera.</p><p>Assembly is modular, solder-free, and plug-and-play. The kit ships with a full project-based curriculum covering Python (MAVSDK), ROS 2, OpenCV, and DroneBlocks visual programming, taking you from unboxing to autonomous code with no technical barrier.</p><ul><li><a href="./../complete_vehicles_mc/droneblocks_dexi">PX4 documentation</a></li><li><a href="https://learn.droneblocks.io/" target="_blank" rel="noreferrer">Manufacturer curriculum</a></li></ul><h2 id="holybro-x500-v2" tabindex="-1">Holybro X500 v2 <a class="header-anchor" href="#holybro-x500-v2" aria-label="Permalink to &quot;Holybro X500 v2&quot;">​</a></h2><p><img src="'+o+'" alt="The fully built X500 v2 with props removed"></p><p>The <a href="https://holybro.com/products/px4-development-kit-x500-v2" target="_blank" rel="noreferrer">PX4 Development Kit X500 v2</a> is a classic 500 mm carbon-fiber quadcopter kit with a Pixhawk 6C or 6X flight controller, M10 GPS, telemetry radio, and power module.</p><p>Motors and ESCs come pre-installed on the arms, so assembly is solder-free and takes about 30 minutes. It lifts a 1.5 kg payload, which makes it a good base for adding your own companion computer and sensors.</p><ul><li><a href="./../frames_multicopter/holybro_x500v2_pixhawk6c">PX4 build guide</a></li><li><a href="https://docs.holybro.com/drone-development-kit/px4-development-kit-x500v2" target="_blank" rel="noreferrer">Manufacturer documentation</a></li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../complete_vehicles_mc/">Complete Vehicles (MC)</a></li><li><a href="./../frames_multicopter/kits">Kit Builds (MC)</a></li><li><a href="./../hardware/dev_kit_program">Developer Kit Program</a> (for manufacturers)</li></ul>',23)])])}const v=t(s,[["render",d]]);export{k as __pageData,v as default};
